// ---------------------------------------------------------------
// Normalize node: extracts sender number and message text from
// the Evolution API v2 webhook payload.
//
// Filters out:
//   - Messages sent BY the bot (fromMe = true)
//   - Group messages (remoteJid ends with @g.us)
//   - Messages with no text content
// ---------------------------------------------------------------
const data = $input.first().json.body?.data;

if (!data) return [];

// Skip messages sent by the bot itself
if (data.key?.fromMe) return [];

const remoteJid = data.key?.remoteJid || '';

// Skip group messages
if (remoteJid.endsWith('@g.us')) return [];

// Extract text from regular, extended, or captioned messages
const text = (
  data.message?.conversation ||
  data.message?.extendedTextMessage?.text ||
  data.message?.imageMessage?.caption ||
  data.message?.videoMessage?.caption ||
  ''
).trim();

if (!text) return [];

// Prefer an alternate JID that explicitly contains the phone number.
// Evolution/Baileys can send @lid JIDs; remoteJidAlt/sender usually
// carry the real @s.whatsapp.net address in that case.
const candidates = [
  data.key?.remoteJidAlt,
  data.key?.senderPn,
  data.sender,
  remoteJid,
].filter(Boolean).map(String);
const phoneJid = candidates.find((j) => j.endsWith('@s.whatsapp.net')) || remoteJid;
const from = phoneJid.replace(/@.*$/, '').replace(/\D/g, '');

if (!from) return [];

return [{
  json: {
    from,
    text,
    cmd: text.toUpperCase().trim()
  }
}];

// ---------------------------------------------------------------
// Rule R5: Unregistered number
// If the number is not in registrations, we reply ONCE telling
// them to register. If they send >3 such messages in 10 min,
// we stay silent (to avoid spamming back).
// ---------------------------------------------------------------
const from = $('Normalize').first().json.from;

return [{ json: { from, action: 'unregistered' } }];

// ---------------------------------------------------------------
// Rule R1 violated: message flood (>10 in 60s)
// Block user for 15 minutes and send a single warning.
// Also checks Rule R4 (repeat offender).
// ---------------------------------------------------------------
const userId = $('Get User').first().json.id;
const from = $('Normalize').first().json.from;

return [{ json: { userId, from, action: 'flood_block' } }];

// ---------------------------------------------------------------
// Main command router.
// Reads cmd (uppercase text) and the user's chat_state from
// the registrations table to determine what to do next.
//
// Global commands (any state): CANCEL, HELP
// State-specific: BOOK (IDLE), STATUS (IDLE), or the current
//   booking flow step (ASK_CATEGORY, ASK_QTY, etc.)
// ---------------------------------------------------------------
const user = $('Get User').first().json;
const norm = $('Normalize').first().json;
const cmd = norm.cmd;
const text = norm.text;
const state = user.chat_state || 'IDLE';
let context = user.chat_context || {};
if (typeof context === 'string') context = JSON.parse(context);

const CATEGORIES = { '1': 'phone', '2': 'laptop', '3': 'battery', '4': 'appliance', '5': 'cables', '6': 'other' };

// Build response object
let result = {
  userId: user.id,
  from: norm.from,
  state: state,
  newState: state,
  context: context,
  newContext: context,
  replyText: '',
  action: 'reply',           // reply | book | none
  bookingData: null
};

// --- Global commands ---
if (cmd === 'CANCEL') {
  result.newState = 'IDLE';
  result.newContext = {};
  result.replyText = '❌ Cancelled. Type BOOK to start a new pickup or HELP for commands.';
  return [{ json: result }];
}

if (cmd === 'HELP') {
  result.replyText = `📋 *Available Commands:*\n\n*BOOK* — Schedule an e-waste pickup\n*STATUS* — View your recent bookings\n*CANCEL* — Cancel the current operation\n*HELP* — Show this message`;
  return [{ json: result }];
}

// --- State machine ---
switch (state) {
  case 'IDLE':
    if (cmd === 'BOOK') {
      result.action = 'check_booking_limits';
      result.replyText = '';
      return [{ json: result }];
    }
    if (cmd === 'STATUS') {
      result.action = 'show_status';
      return [{ json: result }];
    }
    // Default for IDLE
    result.replyText = `Hi ${user.full_name}! 👋\n\nType *BOOK* to schedule an e-waste pickup\nType *STATUS* to see your bookings\nType *HELP* for all commands`;
    return [{ json: result }];

  case 'ASK_CATEGORY':
    if (CATEGORIES[cmd] || CATEGORIES[text]) {
      const cat = CATEGORIES[cmd] || CATEGORIES[text];
      result.newState = 'ASK_QTY';
      result.newContext = { ...context, category: cat };
      result.replyText = `📦 Category: *${cat}*\n\nHow many items? (1-50)`;
    } else {
      result.replyText = `Sorry, I didn't get that. Please reply with a number:\n\n1️⃣ Phone\n2️⃣ Laptop\n3️⃣ Battery\n4️⃣ Appliance\n5️⃣ Cables\n6️⃣ Other`;
    }
    return [{ json: result }];

  case 'ASK_QTY':
    const qty = /^\d+$/.test(text.trim()) ? parseInt(text, 10) : NaN;
    if (isNaN(qty) || qty < 1 || qty > 50) {
      result.replyText = 'Sorry, I didn\'t get that. Please enter a number between 1 and 50.';
    } else {
      result.newState = 'ASK_ADDRESS';
      result.newContext = { ...context, quantity: qty };
      let addrMsg = '📍 Please enter the pickup address.';
      if (user.default_address) {
        addrMsg += '\n\nReply *SAME* to use your saved address:\n' + user.default_address;
      }
      result.replyText = addrMsg;
    }
    return [{ json: result }];

  case 'ASK_ADDRESS':
    let address = text;
    if (cmd === 'SAME' && user.default_address) {
      address = user.default_address;
    }
    if (address.length < 5) {
      result.replyText = 'Sorry, the address seems too short. Please enter a full pickup address.';
    } else {
      result.newState = 'ASK_DATE';
      result.newContext = { ...context, address: address };
      result.replyText = '📅 Pickup date? Format: *DD-MM-YYYY*\n(Must be within the next 14 days)';
    }
    return [{ json: result }];

  case 'ASK_DATE':
    // Parse DD-MM-YYYY
    const parts = text.match(/^(\d{1,2})-(\d{1,2})-(\d{4})$/);
    if (!parts) {
      result.replyText = 'Sorry, I didn\'t get that. Please enter the date in *DD-MM-YYYY* format.';
      return [{ json: result }];
    }
    const day = parseInt(parts[1]);
    const month = parseInt(parts[2]) - 1;
    const year = parseInt(parts[3]);
    const pickupDate = new Date(year, month, day);
    const validComponents = pickupDate.getFullYear() === year && pickupDate.getMonth() === month && pickupDate.getDate() === day;
    const today = new Date();
    today.setHours(0, 0, 0, 0);
    const maxDate = new Date(today);
    maxDate.setDate(maxDate.getDate() + 14);

    if (!validComponents || isNaN(pickupDate.getTime())) {
      result.replyText = 'Invalid date. Please enter a valid date in *DD-MM-YYYY* format.';
    } else if (pickupDate <= today) {
      result.replyText = 'The date must be in the future. Please try again.';
    } else if (pickupDate > maxDate) {
      result.replyText = 'The date must be within the next 14 days. Please try again.';
    } else {
      const dateStr = `${String(day).padStart(2,'0')}-${String(month+1).padStart(2,'0')}-${year}`;
      const isoDate = `${year}-${String(month+1).padStart(2,'0')}-${String(day).padStart(2,'0')}`;
      result.newState = 'CONFIRM';
      result.newContext = { ...context, pickup_date: isoDate, pickup_date_display: dateStr };
      result.replyText = `📋 *Booking Summary:*\n\n` +
        `📦 Category: *${context.category}*\n` +
        `🔢 Quantity: *${context.quantity}*\n` +
        `📍 Address: ${context.address}\n` +
        `📅 Date: *${dateStr}*\n\n` +
        `Reply *YES* to confirm or *CANCEL* to abort.`;
    }
    return [{ json: result }];

  case 'CONFIRM':
    if (cmd === 'YES') {
      // Generate booking reference: EW- + 6 random alphanumerics
      const chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789';
      let ref = 'EW-';
      for (let i = 0; i < 6; i++) ref += chars[Math.floor(Math.random() * chars.length)];
      result.action = 'book';
      result.newState = 'IDLE';
      result.bookingData = {
        booking_ref: ref,
        registration_id: user.id,
        item_category: context.category,
        quantity: context.quantity,
        pickup_address: context.address,
        pickup_date: context.pickup_date
      };
      result.newContext = {};
      result.replyText = `✅ *Booked!* Your reference is *${ref}*\n\nWe'll pick up your ${context.category} (x${context.quantity}) on ${context.pickup_date_display}.\n\nType *STATUS* to check your bookings.`;
    } else {
      result.replyText = 'Please reply *YES* to confirm or *CANCEL* to abort.';
    }
    return [{ json: result }];

  default:
    result.newState = 'IDLE';
    result.newContext = {};
    result.replyText = 'Something went wrong. Type *HELP* for available commands.';
    return [{ json: result }];
}

// Rule R2 violated — daily booking cap
const from = $('Normalize').first().json.from;
const userId = $('Command Router').first().json.userId;
return [{ json: { from, userId, reason: 'daily_booking_cap' } }];

// Format the last 3 bookings for WhatsApp display.
// The query returns a single row whose `bookings` field is a JSON array,
// so this node still runs even when the user has no bookings.
const row = $input.first().json;
const bookings = Array.isArray(row.bookings) ? row.bookings : [];
const from = $('Normalize').first().json.from;

if (bookings.length === 0) {
  return [{ json: { from, text: 'You have no bookings yet. Type *BOOK* to schedule a pickup!' } }];
}

let msg = '📋 *Your Recent Bookings:*\n';
for (const b of bookings) {
  const date = b.pickup_date ? new Date(b.pickup_date).toLocaleDateString('en-IN') : 'N/A';
  msg += `\n🔖 *${b.booking_ref}*\n   ${b.item_category} (x${b.quantity}) — ${date}\n   Status: ${b.status}\n`;
}

return [{ json: { from, text: msg } }];

// Rule R3 violated — pending booking cap
const from = $('Normalize').first().json.from;
const userId = $('Command Router').first().json.userId;
return [{ json: { from, userId, reason: 'pending_cap' } }];
